css:
@media (min-width: 768px) {
  .orders-card { overflow-x: auto; }
  .orders-table { min-width: 760px; }
  .orders-card::-webkit-scrollbar { height: 8px; }
  .orders-card::-webkit-scrollbar-track { background: #eef0f3; border-radius: 4px; }
  .orders-card::-webkit-scrollbar-thumb { background: #b7bec8; border-radius: 4px; }
}
